// CRM columns plus a 0-100 fit score. Rows with no name (pages that could not be read) are dropped.
const form = $('Describe the companies').first().json;
const wanted = [].concat(form['Company sizes'] || []);
const today = new Date().toISOString().slice(0, 10);
return $input.all().map(i => i.json).filter(c => c.name).map(c => {
  let score = 40;
  if (!wanted.length || wanted.some(s => (c.companySize || '').startsWith(s))) score += 20;
  if ((c.foundVia || '').startsWith('hiring')) score += 20;
  if ((c.followers || 0) >= 1000) score += 10;
  if (c.website) score += 10;
  return { json: {
    fit_score: Math.min(score, 100),
    company: c.name,
    website: c.website || '',
    domain: c.domain || '',
    linkedin: c.url,
    industry: c.industry || '',
    size: c.companySize || '',
    employees_on_linkedin: c.employeesOnLinkedIn ?? '',
    followers: c.followers ?? '',
    headquarters: c.headquarters || '',
    country: (c.address || {}).country || '',
    founded: c.foundedYear ?? '',
    specialties: (c.specialties || []).slice(0, 8).join(', '),
    found_via: c.foundVia || '',
    search: form['Keywords'] || '',
    added: today,
  } };
});

// Drop companies already in the sheet (same LinkedIn page or same domain), best fit first.
const norm = u => String(u || '').toLowerCase().replace(/^https?:\/\/(www\.)?/, '').replace(/\/+$/, '');
const existing = $input.all().map(i => i.json);
const seenLinks = new Set(existing.map(r => norm(r.linkedin)).filter(Boolean));
const seenDomains = new Set(existing.map(r => String(r.domain || '').toLowerCase()).filter(Boolean));
const fresh = [];
for (const item of $('Score and flatten').all()) {
  const r = item.json;
  const link = norm(r.linkedin), domain = String(r.domain || '').toLowerCase();
  if (seenLinks.has(link) || (domain && seenDomains.has(domain))) continue;
  seenLinks.add(link);
  if (domain) seenDomains.add(domain);
  fresh.push(r);
}
fresh.sort((a, b) => b.fit_score - a.fit_score);
return fresh.map(json => ({ json }));

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// One e-mail to the requester with the count and the top 10 new companies.
const form = $('Describe the companies').first().json;
const rows = $('Keep only new companies').all().map(i => i.json);
const found = $('Score and flatten').all().length;
const top = rows.slice(0, 10).map(r => `<tr><td>${r.fit_score}</td><td><a href="${esc(r.linkedin)}">${esc(r.company)}</a></td><td>${esc(r.industry)}</td><td>${esc(r.size)}</td><td>${esc(r.headquarters)}</td></tr>`).join('');
return [{ json: {
  sendTo: form['Send results to'],
  subject: `${rows.length} new companies added for "${form['Keywords']}"`,
  html: `<div style="font-family:Arial,sans-serif;font-size:14px"><p>${found} companies matched; ${rows.length} were new and are now in your sheet (${found - rows.length} were already there).</p><table cellpadding="6" style="border-collapse:collapse"><tr><th align="left">Fit</th><th align="left">Company</th><th align="left">Industry</th><th align="left">Size</th><th align="left">HQ</th></tr>${top}</table></div>`,
} }];
